const defaults=[{list:'PLS7NuVuIPeHjj_XgaQVAWhBbMpQKkR35L',video:'dokLwszdUgY',index:1},{list:'PLS7NuVuIPeHh3ND9y6EnpMqTlGuVAMwF1',video:'8sC0zvwSF50',index:0}];
let saved={};try{saved=JSON.parse(localStorage.getItem('interval-v1'))||{}}catch{}
const $=s=>document.querySelector(s), decks=[], titles=new Map(), pending=new Set();let metadataQueue=[],activeRequests=0;
const clamp=(x,def)=>Number.isFinite(Number(x))?Math.max(0,Math.min(100,Number(x))):def;
$('#cross').value=clamp(saved.cross??50,50);$('#master').value=clamp(saved.master??80,80);
function persist(){try{localStorage.setItem('interval-v1',JSON.stringify({cross:+$('#cross').value,master:+$('#master').value,decks:decks.map(d=>({list:d.list,video:d.video,index:d.index,volume:+d.volume.value}))}))}catch{}}
function status(d,s){d.status.textContent=s}
function mix(save=true){let x=+$('#cross').value/100,m=+$('#master').value/100;const gains=[Math.cos(x*Math.PI/2),Math.sin(x*Math.PI/2)];decks.forEach((d,i)=>{if(d.ready)d.player.setVolume(Math.round(gains[i]*m*d.volume.value))});$('#mixread').textContent=`A ${Math.round(gains[0]*100)}% · B ${Math.round(gains[1]*100)}%`;$('#masterread').textContent=Math.round(m*100)+'%';if(save)persist()}
function metadata(id){if(titles.has(id)||pending.has(id))return;pending.add(id);metadataQueue.push(id);pump()}
function pump(){while(activeRequests<4&&metadataQueue.length){const id=metadataQueue.shift();activeRequests++;fetch('https://www.youtube.com/oembed?url='+encodeURIComponent('https://www.youtube.com/watch?v='+id)+'&format=json',{signal:AbortSignal.timeout(6000)}).then(r=>{if(!r.ok)throw Error();return r.json()}).then(j=>{titles.set(id,{title:j.title,author:j.author_name});document.querySelectorAll('[data-video="'+id+'"]').forEach(row=>{row.querySelector('strong').textContent=j.title;row.querySelector('small').textContent=j.author_name})}).catch(()=>{}).finally(()=>{activeRequests--;pump()})}}
function render(d,ids){d.ids=ids;d.tracks.replaceChildren();d.count.textContent=ids.length+' titres';ids.forEach((id,i)=>{const row=document.createElement('button');row.className='track';row.dataset.video=id;const num=document.createElement('span');num.className='num';num.textContent=String(i+1).padStart(2,'0');const img=document.createElement('img');img.src='https://i.ytimg.com/vi/'+id+'/default.jpg';img.alt='';img.loading='lazy';const text=document.createElement('span');text.className='text';const title=document.createElement('strong');title.textContent=titles.get(id)?.title||'Vidéo · '+id;const sub=document.createElement('small');sub.textContent=titles.get(id)?.author||'YouTube';text.append(title,sub);row.append(num,img,text);row.onclick=()=>{if(d.ready){resetLoop(d);d.player.playVideoAt(i);d.index=i;persist()}};d.tracks.append(row);metadata(id)});highlight(d)}
function highlight(d){if(!d.ready)return;const i=d.player.getPlaylistIndex();Array.from(d.tracks.children).forEach((row,n)=>{row.classList.toggle('active',n===i);row.setAttribute('aria-current',n===i?'true':'false')})}
function rates(d){const values=d.player.getAvailablePlaybackRates()||[1];const signature=values.join();if(d.rate.dataset.rates!==signature){d.rate.replaceChildren();values.forEach(v=>{const o=document.createElement('option');o.value=v;o.textContent=v+'×';d.rate.append(o)});d.rate.dataset.rates=signature}d.rate.value=String(d.player.getPlaybackRate()||1)}
function sync(d){if(!d.ready)return;const ids=d.player.getPlaylist();if(d.pendingRate!=null&&[1,2,5].includes(d.player.getPlayerState())){const v=d.player.getVideoData();if(v?.video_id===d.restoreVideo||(ids?.join()!==d.previousIds&&ids?.length)){const target=d.pendingRate;d.pendingRate=null;d.player.setPlaybackRate(target);}}if(ids?.length&&ids.join()!==d.ids.join())render(d,ids);highlight(d);rates(d);const data=d.player.getVideoData();if(data?.title){const id=data.video_id;titles.set(id,{title:data.title,author:data.author});d.tracks.querySelectorAll('[data-video="'+id+'"]').forEach(row=>{row.querySelector('strong').textContent=data.title;row.querySelector('small').textContent=data.author||'YouTube'})}}
function parse(raw){let u;try{u=new URL(raw.replaceAll('\\',''))}catch{throw Error('Collez un lien YouTube contenant une playlist.')}if(!['youtube.com','www.youtube.com','m.youtube.com','music.youtube.com','youtu.be'].includes(u.hostname))throw Error('Ce lien ne provient pas de YouTube.');const list=u.searchParams.get('list');if(!list||!/^[-\w]+$/.test(list))throw Error('Le lien doit contenir une playlist (list=…).');return {list,video:u.searchParams.get('v')||'',index:Math.max(0,(parseInt(u.searchParams.get('index'))||1)-1)}}
['A','B'].forEach((letter,i)=>{const config=saved.decks?.[i];const initial=config&&/^[-\w]+$/.test(config.list)?config:defaults[i];const root=$('#deck'+letter);root.innerHTML=`<div class="deck-top"><div class="deck-head"><span class="badge">${letter}</span><div><h2>Playlist ${letter}</h2><div class="sub">PLATINE ${String(i+1).padStart(2,'0')}</div></div><a class="external" target="_blank" rel="noopener" aria-label="Ouvrir la playlist ${letter} sur YouTube">↗</a></div><span class="playlist-title" title="Nom de la playlist">Chargement…</span><form class="urlform"><input aria-label="Lien de la playlist ${letter}" type="url" required><button type="submit">Charger</button></form></div><div class="video"><div id="player${letter}"></div></div><div class="status" aria-live="polite">Connexion à YouTube…</div><div class="controls"><button data-action="prev" aria-label="Morceau précédent ${letter}" disabled>⏮</button><button class="play" data-action="play" disabled>▶ Lecture</button><button data-action="pause" aria-label="Pause ${letter}" disabled>Ⅱ</button><button data-action="next" aria-label="Morceau suivant ${letter}" disabled>⏭</button></div><div class="volume-speed"><div class="volume"><label for="volume${letter}">Volume</label><input id="volume${letter}" type="range" min="0" max="100" value="85"><output>85%</output></div><div class="speed"><label for="rate${letter}">Vitesse</label><select id="rate${letter}" title="Vitesses disponibles selon la vidéo" disabled><option value="1">1×</option></select></div></div><div class="listhead"><span>COLLECTION ${letter}</span><span class="count">En attente</span></div><div class="tracks"><p class="empty">La liste apparaîtra dès que le lecteur YouTube l’aura chargée. Si nécessaire, lancez la lecture dans la vidéo.</p></div>`;
const d={...initial,letter,root,ids:[],ready:false,volume:root.querySelector('input[type=range]'),rate:root.querySelector('select'),status:root.querySelector('.status'),tracks:root.querySelector('.tracks'),count:root.querySelector('.count')};decks.push(d);refreshPlaylistTitle(d);d.volume.value=clamp(config?.volume??85,85);d.volume.nextElementSibling.textContent=d.volume.value+'%';const input=root.querySelector('input[type=url]');input.value='https://www.youtube.com/playlist?list='+d.list;root.querySelector('a').href=input.value;
root.querySelector('form').onsubmit=e=>{e.preventDefault();try{const next=parse(input.value);d.pendingRate=null;resetLoop(d);Object.assign(d,next);refreshPlaylistTitle(d);d.ids=[];d.tracks.replaceChildren();d.count.textContent='Chargement…';root.querySelector('a').href='https://www.youtube.com/playlist?list='+d.list;status(d,'Chargement de la playlist…');reloadDeck(d);persist()}catch(err){status(d,err.message)}};
d.volume.oninput=()=>{d.volume.nextElementSibling.textContent=d.volume.value+'%';mix()};d.rate.onchange=()=>{if(d.ready)d.player.setPlaybackRate(Number(d.rate.value))};root.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{if(!d.ready)return;const action=b.dataset.action;if(action==='play')d.player.playVideo();if(action==='pause')d.player.pauseVideo();if(action==='next'){resetLoop(d);d.player.nextVideo()}if(action==='prev'){resetLoop(d);d.player.previousVideo()}});});
function updateTransport(){
 const ready=decks.every(d=>d.ready);
 document.querySelectorAll('#save-mixtape,#mixtape-menu,.global-transport button').forEach(b=>b.disabled=!ready);
}
function reloadDeck(d){
 d.ready=false;
 d.generation=(d.generation||0)+1;
 d.root.querySelectorAll('[data-action],select').forEach(b=>b.disabled=true);
 updateTransport();
 if(d.player){d.player.destroy();d.player=null;}
 const mount=document.createElement('div');mount.id='player'+d.letter;
 d.root.querySelector('.video').replaceChildren(mount);
 // Before the API is ready, the latest requested playlist is kept on the deck.
 if(window.YT?.Player)createDeckPlayer(d);
}
function createDeckPlayer(d){
 const generation=d.generation||0;
 const current=()=>generation===(d.generation||0);
 d.player=new YT.Player('player'+d.letter,{width:'100%',height:'100%',playerVars:{listType:'playlist',list:d.list,index:d.index,autoplay:0,playsinline:1,origin:location.origin},events:{onReady:()=>{if(!current())return;d.ready=true;if(decks.every(deck=>deck.ready)){document.querySelectorAll('#save-mixtape,#mixtape-menu').forEach(b=>b.disabled=false)}document.querySelectorAll('.global-transport button').forEach(b=>b.disabled=!decks.every(deck=>deck.ready));d.root.querySelectorAll('[data-action],select').forEach(b=>b.disabled=false);status(d,'Prêt · cliquez sur Lecture pour commencer.');mix();sync(d)},onStateChange:e=>{if(!current())return;const labels={'1':'Lecture en cours','2':'En pause','3':'Chargement…','0':'Morceau terminé','5':'Prêt à lire','-1':'Prêt à lire'};status(d,labels[e.data]||'Prêt');if(typeof loopTick==='function')loopTick(d);sync(d)},onPlaybackRateChange:()=>{if(current())rates(d)},onAutoplayBlocked:()=>{if(current())status(d,'Cliquez sur Lecture directement dans le lecteur YouTube.')},onError:e=>{if(!current())return;const errors={2:'Lien ou identifiant non valide.',5:'Le navigateur ne peut pas lire cette vidéo.',100:'Vidéo supprimée ou privée.',101:'Intégration refusée par cette vidéo.',150:'Intégration refusée par cette vidéo.',153:'YouTube ne reconnaît pas l’origine de la page.'};status(d,(errors[e.data]||'Lecture indisponible.')+' Essayez le titre suivant ou ouvrez YouTube.')}}});
}
window.onYouTubeIframeAPIReady=()=>decks.forEach(createDeckPlayer);
$('#cross').oninput=mix;$('#master').oninput=mix;$('#center').onclick=()=>{$('#cross').value=50;mix()};$('#playall').onclick=()=>decks.forEach(d=>{if(d.ready){mix();d.player.playVideo()}});$('#pauseall').onclick=()=>decks.forEach(d=>{if(d.ready)d.player.pauseVideo()});$('#stopall').onclick=()=>{if(typeof cancelFade==='function')cancelFade();decks.forEach(d=>{if(d.ready){if(d.loop){d.loop.enabled=false;paintLoop(d)}d.player.pauseVideo();d.player.seekTo(0,true);d.player.pauseVideo()}})};$('#help').onclick=()=>$('#guide').showModal();$('#closehelp').onclick=()=>$('#guide').close();mix();
setInterval(()=>decks.forEach(sync),1500);const script=document.createElement('script');script.src='https://www.youtube.com/iframe_api';script.onerror=()=>decks.forEach(d=>status(d,'YouTube est inaccessible. Vérifiez la connexion et les autorisations du navigateur.'));document.head.append(script);setTimeout(()=>decks.filter(d=>!d.ready).forEach(d=>status(d,'YouTube tarde à répondre. Vérifiez la connexion ou rechargez la page.')),15000);
